const $=id=>document.getElementById('M40-'+id),zh=document.documentElement.lang.startsWith('zh'),tr=(z,e)=>zh?z:e;
if(!$('board'))return;
let model='True',method='ULA',h=.04,initial='spread',background='energy',points=[],trail=[],counts=[0,0,0,0],steps=0,accepted=0,proposed=0,switches=0,rng=4001,timer=null;
const uniform=()=>{rng=(Math.imul(1664525,rng)+1013904223)>>>0;return(rng+.5)/4294967296},normal=()=>Math.sqrt(-2*Math.log(uniform()))*Math.cos(2*Math.PI*uniform());
function energyGradient(x){
 if(model==='True'){
  const a=data.centers.map((m,i)=>Math.log(data.weights[i])-((x[0]-m[0])**2+(x[1]-m[1])**2)/(2*data.variance)),max=Math.max(...a),w=a.map(v=>Math.exp(v-max)),z=w.reduce((a,b)=>a+b,0),g=[0,0];
  w.forEach((v,i)=>{g[0]+=v/z*(x[0]-data.centers[i][0])/data.variance;g[1]+=v/z*(x[1]-data.centers[i][1])/data.variance});
  return {e:Math.log(2*Math.PI*data.variance)-max-Math.log(z),g};
 }
 const n=data.network,W0=n['net.0.weight'],W1=n['net.2.weight'],W2=n['net.4.weight'][0];
 const a=W0.map((row,i)=>Math.tanh(row[0]*x[0]+row[1]*x[1]+n['net.0.bias'][i]));
 const b=W1.map((row,i)=>Math.tanh(row.reduce((s,v,j)=>s+v*a[j],n['net.2.bias'][i])));
 const back=b.map((v,i)=>W2[i]*(1-v*v)),g=x.slice();
 a.forEach((v,j)=>{let s=0;for(let i=0;i<32;i++)s+=back[i]*W1[i][j];s*=1-v*v;g[0]+=s*W0[j][0];g[1]+=s*W0[j][1]});
 return {e:.5*(x[0]**2+x[1]**2)+b.reduce((s,v,i)=>s+v*W2[i],n['net.4.bias'][0]),g};
}
const quad=x=>x[1]<0?(x[0]<0?0:1):(x[0]>=0?2:3),squared=x=>x[0]**2+x[1]**2;
function advance(n){for(let k=0;k<n;k++){
 points=points.map(x=>{const a=energyGradient(x),y=x.map((v,j)=>v-h*a.g[j]+Math.sqrt(2*h)*normal());let accept=true;
  if(method==='MALA'){const b=energyGradient(y),forward=squared(y.map((v,j)=>v-x[j]+h*a.g[j]))/(4*h),back=squared(x.map((v,j)=>v-y[j]+h*b.g[j]))/(4*h);accept=Math.log(uniform())<Math.min(0,-b.e+a.e+forward-back)}
  proposed++;if(accept)accepted++;const result=accept?y:x;if(quad(result)!==quad(x))switches++;counts[quad(result)]++;return result;
 });steps++;trail.push(points[0].slice());
 }render()}
function stop(){if(timer!==null)clearInterval(timer);timer=null}
function initialize(){stop();rng=4001;steps=accepted=proposed=switches=0;counts=[0,0,0,0];points=Array.from({length:16},(_,i)=>data.centers[initial==='one'?0:i%4].slice());trail=[points[0].slice()]}
function render(){
 ['model','method','initial','background'].forEach(k=>$(k).value=({model,method,initial,background})[k]);$('h').value=String(h);$('play').textContent=timer===null?tr('播放','Play'):tr('暂停','Pause');
 const extent=Math.max(4,Math.ceil(Math.max(...points.flat().map(Math.abs),...trail.flat().map(Math.abs)))),left=70,top=45,size=480,X=x=>left+(x+extent)/(2*extent)*size,Y=y=>top+(extent-y)/(2*extent)*size;
 const energy=data.energies[model],minimum=Math.min(...energy),values=energy.map(e=>background==='energy'?e-minimum:Math.exp(-e-data.logZ[model]));
 const vmax=background==='energy'?Math.max(...values):Math.max(...values),color=v=>{let t=Math.max(0,Math.min(1,v/vmax));return background==='energy'?`rgb(${Math.round(238-211*t)},${Math.round(244-190*t)},${Math.round(247-168*t)})`:`rgb(${Math.round(247-224*t)},${Math.round(246-124*t)},${Math.round(229-100*t)})`};
 let svg='<rect width="1140" height="680" fill="#fff"/>';
 for(let iy=0;iy<60;iy++)for(let ix=0;ix<60;ix++){let i=iy*60+ix;let xx=data.grid[i][0]-4/60,yy=data.grid[i][1]-4/60;svg+=`<rect x="${X(xx)}" y="${Y(yy+8/60)}" width="${size/(2*extent)*8/60+.2}" height="${size/(2*extent)*8/60+.2}" fill="${color(values[i])}"/>`}
 svg+=`<rect x="${left}" y="${top}" width="${size}" height="${size}" fill="none" stroke="#293c4b"/><path d="M ${X(0)} ${top} V ${top+size} M ${left} ${Y(0)} H ${left+size}" stroke="#8498a0" stroke-dasharray="3 4"/>`;
 for(let v=-extent;v<=extent;v+=extent/2)svg+=`<text x="${X(v)}" y="${top+size+24}" text-anchor="middle" font-size="14">${v}</text><text x="${left-12}" y="${Y(v)+5}" text-anchor="end" font-size="14">${v}</text>`;
 svg+=`<text x="310" y="580" text-anchor="middle" font-size="17">x₁</text><text x="24" y="285" font-size="17">x₂</text><text x="70" y="25" font-size="19">${background==='energy'?tr('相对能量 E − min E','Relative energy E − min E'):tr('概率密度 p(x)','Probability density p(x)')}</text>`;
 svg+=`<polyline points="${trail.map(p=>X(p[0])+','+Y(p[1])).join(' ')}" fill="none" stroke="#d56240" stroke-width="1.4" opacity=".8"/>`;
 points.forEach((p,i)=>svg+=`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="${i===0?5:3.8}" fill="${i===0?'#d64b2b':'#117bab'}" stroke="#fff" stroke-width=".8"/>`);
 for(let k=0;k<80;k++)svg+=`<rect x="${left+k*6}" y="610" width="6.2" height="13" fill="${color(vmax*k/79)}"/>`;
 svg+=`<text x="70" y="646" font-size="14">0</text><text x="550" y="646" text-anchor="end" font-size="14">${vmax.toFixed(3)}</text>`;
 const target=model==='True'?data.quadrant_weights:data.learned_quadrant_weights,observed=steps?counts.map(v=>v/(steps*16)):counts.map(()=>0),bx=650,by=435,bh=320;
 svg+=`<text x="650" y="45" font-size="19">${tr('象限概率：模型与链','Quadrant mass: model and chain')}</text>`;
 [0,.2,.4,.6,.8,1].forEach(v=>{svg+=`<line x1="650" y1="${by-v*bh}" x2="1095" y2="${by-v*bh}" stroke="#e7edf0"/><text x="637" y="${by-v*bh+5}" text-anchor="end" font-size="14">${v.toFixed(1)}</text>`});
 target.forEach((v,i)=>{let x=bx+28+i*108;svg+=`<rect x="${x}" y="${by-v*bh}" width="28" height="${v*bh}" fill="#8498a4"/><rect x="${x+31}" y="${by-observed[i]*bh}" width="28" height="${observed[i]*bh}" fill="#117bab"/><text x="${x+30}" y="465" text-anchor="middle" font-size="15">${['− −','+ −','+ +','− +'][i]}</text><text x="${x+30}" y="488" text-anchor="middle" font-size="13">${observed[i].toFixed(3)}</text>`});
 svg+=`<rect x="650" y="525" width="16" height="16" fill="#8498a4"/><text x="675" y="539" font-size="15">${tr('模型概率质量','Model mass')}</text><rect x="875" y="525" width="16" height="16" fill="#117bab"/><text x="900" y="539" font-size="15">${tr('链累计频率','Chain frequency')}</text>`;
 const tv=steps?.5*target.reduce((s,v,i)=>s+Math.abs(v-observed[i]),0):null;
 svg+=`<text x="650" y="585" font-size="17">${tr('步数','Steps')}: ${steps} · ${tr('象限 TV','Quadrant TV')}: ${tv===null?'—':tv.toFixed(3)}</text><text x="650" y="618" font-size="17">${tr('接受率','Acceptance')}: ${proposed?(accepted/proposed).toFixed(3):'—'} · ${tr('跨象限次数','Crossings')}: ${switches}</text>`;
 $('board').innerHTML=svg;$('status').textContent=tr('第一条链坐标：','First chain: ')+points[0].map(v=>v.toFixed(5)).join(', ')+tr('；累计状态数：','; accumulated states: ')+(16*steps)+tr('。拒绝后位置仍参与统计。',' . Rejected moves still contribute their retained states.');
}
function state(){let p=energyGradient([.5,-.25]);return {model,method,h,initial,background,steps,playing:timer!==null,firstX:points[0][0],firstY:points[0][1],accepted,proposed,switches,counts:counts.slice(),probeEnergy:p.e,probeGX:p.g[0],probeGY:p.g[1]}}
function set(p={}){stop();if(p.model)model=p.model;if(p.method)method=p.method;if(p.initial)initial=p.initial;if(p.background)background=p.background;if(p.h!==undefined)h=+p.h;initialize();if(p.steps)advance(Math.max(0,Math.min(10000,Math.floor(p.steps))));else render();return state()}
function reset(){model='True';method='ULA';h=.04;initial='spread';background='energy';initialize();render();return state()}
['model','method','initial','h'].forEach(k=>$(k).addEventListener('change',()=>{const p={model,method,h,initial,background};p[k]=$(k).value;set(p)}));
$('background').addEventListener('change',()=>{background=$('background').value;render()});
$('step').addEventListener('click',()=>{stop();advance(10)});$('play').addEventListener('click',()=>{if(timer!==null)stop();else timer=setInterval(()=>advance(10),350);render()});$('reset').addEventListener('click',reset);
window.CourseLab={state,set,reset,destroy:stop};reset();

